/* On-demand, source-based translation ledger. No remote embeds or note writes. */
(() => {
 'use strict';const root=document.getElementById('translation');if(!root)return;
 const q=id=>document.getElementById('translation-'+id),E=globalThis.AtlasZh?.escape||String;
 const labels={'body-summary':'已讀正文・繁中摘要','intro-only':'僅公開介紹摘要','licensed-excerpt':'授權指定選段','excerpt-summary':'短句／部分內容摘要','pending':'待讀取內容','unavailable':'本次無法取得'};
 let index=null,limit=12,loading=null,revision=0;const chunks=new Map();
 const safe=u=>{try{const x=new URL(u);return /^https?:$/.test(x.protocol)?x.href:'#';}catch{return '#';}};
 const link=(u,t)=>'<a href="'+E(safe(u))+'" target="_blank" rel="noopener noreferrer">'+E(t)+' ↗</a>';
 async function json(file){const r=await fetch(file,{cache:'no-cache'});if(!r.ok)throw Error('無法載入來源清單');return r.json();}
 async function detail(row){if(!chunks.has(row.chunk))chunks.set(row.chunk,json('translation/'+row.chunk).catch(e=>{chunks.delete(row.chunk);throw e;}));const list=await chunks.get(row.chunk);const result=list.find(r=>r.id===row.id);if(!result)throw Error('來源版本不一致，請重新整理');return result;}
 function card(s){const reviewed=s.status!=='pending'&&s.status!=='unavailable',date=s.checked?'來源查核 '+s.checked:'尚未讀取原文；盤點 '+s.inventoried;return '<article class="translation-card card" id="translation-source-'+E(s.id)+'" data-status="'+E(s.status)+'"><span class="translation-status">'+E(labels[s.status]||s.status)+'</span><h3>'+E(s.titleZh)+'</h3><p class="translation-scope">'+E(date)+'<br>'+(s.titleCoverage==='existing-label'?'目前標題為既有主題標籤，原題仍待逐筆翻譯。':s.titleCoverage==='title-only'?'原題已譯；標題翻譯不代表正文摘要完成。':'題名與讀取範圍已查核。')+'</p>'+(s.summaryZh?'<p><strong>'+E(s.summaryZh)+'</strong></p>':'<p>尚未提供內容摘要。需實際讀取原文或影音內容後才能完成。</p>')+'<p><strong>實際讀取範圍：</strong>'+E(s.readScope)+'</p>'+(s.keyPointsZh?.length?'<ul>'+s.keyPointsZh.map(t=>'<li>'+E(t)+'</li>').join('')+'</ul>':'')+(s.limitsZh?'<p><strong>限制：</strong>'+E(s.limitsZh)+'</p>':'')+(s.attributionNoteZh?'<p><strong>作者更正：</strong>'+E(s.attributionNoteZh)+'</p>':'')+'<details class="zh-original"><summary>展開英文原題與網址</summary><div lang="en">'+E(s.sourceTitle)+'</div><p>'+link(s.url,'開啟原始來源')+'</p></details>'+(s.courseRefs||[]).map(r=>'<p class="translation-scope"><strong>'+E(r.version+' '+r.unit+'・'+r.topic)+'</strong><br>'+E(r.relation)+'・'+link(r.url,'官方單元')+'</p>').join('')+'<details><summary>來源紀錄與範圍說明</summary><p>同網址關聯 '+s.locations.length+' 處。去重不代表每段影片或付費內容都已讀。</p>'+(s.evidence?'<p>'+E(s.evidence.accessMethod||'')+'<br>'+E(s.evidence.scope||'')+'</p>':'')+(s.existingLicensed||[]).map(a=>'<p>已翻譯範圍：'+E(a.scope)+'<br><a href="#read/'+E(a.articleId)+'">開啟授權對照 →</a></p>').join('')+(s.existingExcerpt?'<p>既有選讀範圍：'+E(s.existingExcerpt.readScope)+'</p>':'')+'</details><div class="translation-actions">'+link(s.url,reviewed?'對照原文':'查看原始入口')+'</div></article>';}
 async function render(target){
  if(!index)return;const ticket=++revision,terms=q('search').value.normalize('NFKC').toLowerCase().trim().split(/\s+/).filter(Boolean),status=q('filter').value;
  const rows=index.sources.filter(s=>(status==='all'||status===s.status)&&terms.every(t=>[s.titleZh,s.sourceTitle,s.url,...(s.authors||[]),...s.resourceIds].join(' ').normalize('NFKC').toLowerCase().includes(t)));
  q('status').textContent='正在讀取符合條件的來源…';
  try{const details=await Promise.all(rows.slice(0,limit).map(detail));if(ticket!==revision)return;q('grid').innerHTML=details.map(card).join('')||'<p>沒有符合的來源，請縮短關鍵字或清除篩選。</p>';q('status').textContent='顯示 '+details.length+' / '+rows.length+' 筆符合來源（共 '+index.totalSources+' 筆）；正文摘要與介紹／選段分開計數。';q('more').hidden=limit>=rows.length;if(target)document.getElementById('translation-source-'+target)?.scrollIntoView({block:'start'});}
  catch(e){if(ticket!==revision)return;q('status').textContent='來源內容暫時無法載入，可按「重新載入清單」重試。';q('load').hidden=false;q('load').textContent='重新載入清單';}
 }
 async function load(){if(index)return;if(loading)return loading;q('status').textContent='載入全站來源索引…';loading=json('translation/index.json').then(d=>{if(!Array.isArray(d.sources)||d.sources.length!==d.totalSources)throw Error('索引不完整');index=d;const c=d.statusCounts;q('metrics').innerHTML=[[d.totalSources,'去重後的英文來源'],[c['body-summary']||0,'已讀正文摘要'],[(c['intro-only']||0)+(c['licensed-excerpt']||0)+(c['excerpt-summary']||0),'僅介紹／選段'],[(c.pending||0)+(c.unavailable||0),'待讀取／未取得']].map(([n,t])=>'<div><strong>'+n.toLocaleString()+'</strong><span>'+t+'</span></div>').join('');q('controls').hidden=false;q('load').hidden=true;}).catch(e=>{loading=null;q('status').textContent='索引暫時無法載入，請按按鈕重試。';throw e;});return loading;}
 async function route(){if(!location.hash.startsWith('#translation-resource-')&&!location.hash.startsWith('#translation-source-')&&location.hash!=='#translation')return;try{await load();if(location.hash==='#translation'){await render();root.scrollIntoView({block:'start'});return;}const resource=location.hash.startsWith('#translation-resource-'),key=decodeURIComponent(location.hash.slice(resource?'#translation-resource-'.length:'#translation-source-'.length));const row=index.sources.find(s=>resource?s.resourceIds.includes(key):s.id===key);if(!row){q('status').textContent='找不到對應來源，請使用搜尋。';root.scrollIntoView({block:'start'});return;}q('filter').value='all';q('search').value=row.id;q('search').value=row.resourceIds[0]||row.url;limit=12;await render(row.id);}catch{}}
 q('load').addEventListener('click',()=>load().then(()=>render()).catch(()=>{}));q('more').addEventListener('click',()=>{limit+=24;render();});q('search').addEventListener('input',()=>{limit=12;render();});q('filter').addEventListener('change',()=>{limit=12;render();});q('reset').addEventListener('click',()=>{q('search').value='';q('filter').value='all';limit=12;render();});window.addEventListener('hashchange',route);
 if(typeof IntersectionObserver!=='undefined'){const watcher=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){watcher.disconnect();load().then(()=>render()).catch(()=>{});}},{rootMargin:'300px'});watcher.observe(root);}route();
})();
